describe('Error Toast Notification', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should display error toast notification when an action fails', () => {
    // Intercept the API call that should fail
    cy.intercept('POST', '/api/items', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('createItemRequest');

    // Click the button to trigger the failed action
    cy.get('[data-testid="create-item-button"]').click();

    // Wait for the failed API call
    cy.wait('@createItemRequest');

    // Verify error toast appears
    cy.get('[data-testid="error-toast"]')
      .should('be.visible')
      .should('contain', 'Failed to create item');

    // Verify error message content
    cy.get('[data-testid="error-toast"]')
      .should('contain', 'Internal server error');

    // Verify toast has close button and can be dismissed
    cy.get('[data-testid="error-toast-close-button"]').click();
    cy.get('[data-testid="error-toast"]')
      .should('not.exist');
  });

  it('should not display error toast when action succeeds', () => {
    // Intercept the API call that should succeed
    cy.intercept('POST', '/api/items', {
      statusCode: 201,
      body: { id: 123, name: 'New Item' }
    }).as('createItemRequest');

    // Click the button to trigger the successful action
    cy.get('[data-testid="create-item-button"]').click();

    // Wait for the successful API call
    cy.wait('@createItemRequest');

    // Verify success message appears instead of error toast
    cy.get('[data-testid="success-toast"]')
      .should('be.visible')
      .should('contain', 'Item created successfully');

    // Verify error toast does not appear
    cy.get('[data-testid="error-toast"]').should('not.exist');

    // Verify success toast can be dismissed
    cy.get('[data-testid="success-toast-close-button"]').click();
    cy.get('[data-testid="success-toast"]')
      .should('not.exist');
  });
});
